// Function to calculate the nth number in the custom Tribonacci-like sequence
// Uses memoization to avoid recalculating values (Time Complexity: O(n))
long long get_nth_number(int n) {
    // Handle base cases explicitly
    if (n < 0) {
        throw std::invalid_argument("Index cannot be negative.");
    }
    if (n == 0) return 0;
    if (n == 1) return -1;
    if (n == 2) return -1;

    // Vector to store computed values (memoization table)
    // We initialize with 0, but we will fill it as we go.
    // Using long long to prevent overflow for larger n.
    std::vector<long long> memo(n + 1);

    // Fill the table iteratively to avoid stack overflow risks with deep recursion
    // and to keep the code simple and fast.
    memo[0] = 0;
    memo[1] = -1;
    memo[2] = -1;

    for (int i = 3; i <= n; ++i) {
        memo[i] = memo[i - 1] + memo[i - 2] + memo[i - 3];
    }

    return memo[n];
}

